        title: 'What Access Control and Logging Does the Inference Endpoint Need?',
        content: [
          '**An auditor expects to see who called the model, with what credential, and when — a requirement none of the common self-hosted engines satisfy without a gateway in front of them.** Ollama binds to `127.0.0.1:11434` by default and has no user accounts; vLLM and Hugging Face TGI expose an OpenAI-compatible HTTP API with no built-in authentication.',
          'Use an API gateway (Kong, Envoy, or a cloud provider\'s API management layer) in front of the inference engine to add per-caller API keys or OAuth2, then log every request with caller identity, timestamp, model version, and token counts to a system your SIEM can ingest. Avoid logging full prompt/response bodies in the access log itself — keep that in the separately governed prompt-log store covered under data retention below.',
        ],
        items: [
          '**Authentication**: API keys or OAuth2 at the gateway, never a shared bearer token used by every caller',
          '**Authorization**: role-based access — who can call which model, who can see admin/metrics endpoints',
          '**Audit log fields**: caller identity, timestamp, model + version, endpoint called, response status — exported to a log store with restricted write access',
          '**Admin access**: MFA required for anyone with shell or config access to the inference host',
        ],
