        id: 'data-retention',
        title: 'What Should a Data Retention Policy for Prompt Logs Cover?',
        content: [
          '**Prompt logs are the highest-risk data your LLM stack produces, because they often contain the same sensitive content a user would type into any other business system.** A written retention policy — how long logs are kept, who can access them, and how they are deleted — is a control an auditor will specifically ask to see, not just infer from your general data-retention policy.',
          'Use a retention window that matches your actual audit or debugging need, not "keep everything forever by default." Use field-level minimization where possible — log metadata (caller, timestamp, token count, model version) without the full prompt text for routine traffic, and reserve full-content logging for a shorter, more tightly access-controlled window used for debugging or abuse investigation.',
        ],
