    intro: 'Ein selbst gehostetes LLM-Deployment auditfest für SOC 2 Type II oder ISO 27001 zu machen, bedeutet: dieselben Kontrollen nachzuweisen, die ein Auditor bei jedem anderen Produktivsystem prüft — Zugriffskontrolle, Verschlüsselung, Change-Management, Incident Response — angewendet auf Inference-Endpunkt, Modellgewichte und Prompt-Logs. Dieser Leitfaden ordnet diese Kontrollen konkret Ollama, vLLM, Hugging Face TGI und Enterprise-Inference-Plattformen zu.',
