    title: 'SOC 2 et ISO 27001 : préparer un déploiement de LLM auto-hébergé (2026)',
    seoTitle: 'SOC 2 & ISO 27001 : LLM auto-hébergé (2026)',
    intro: 'Préparer un déploiement de LLM auto-hébergé pour un audit SOC 2 Type II ou ISO 27001 revient à démontrer les mêmes contrôles qu\'un auditeur vérifie sur tout système de production — contrôle d\'accès, chiffrement, gestion du changement, réponse aux incidents — appliqués au point de terminaison d\'inférence, aux poids du modèle et aux journaux de prompts. Ce guide relie ces contrôles aux outils réellement utilisés : Ollama, vLLM, Hugging Face TGI et les plateformes d\'inférence d\'entreprise.',
    metaDescription: 'Préparation SOC 2 Type II et ISO 27001 pour un LLM auto-hébergé : Trust Services Criteria, contrôles Annex A, journalisation d\'accès, chiffrement et risque fournisseur pour les modèles open-weight.',
    publishDate: '2026-09-02',
    dateModified: '2026-09-02',
    readTime: '11 min de lecture',
    educationalLevel: 'Advanced',
    audience: 'Responsables IT/sécurité et responsables conformité préparant un déploiement de LLM auto-hébergé pour un audit SOC 2 Type II ou ISO 27001',
