          'Utilisez le critère sécurité si votre rapport ne couvre que le critère de base (obligatoire dans tout rapport SOC 2). Ajoutez disponibilité si le LLM sert un flux de production avec un engagement de disponibilité. Ajoutez confidentialité si les prompts ou sorties contiennent des données contractuellement protégées.',
