      accessControlLogging: {
        id: 'access-control-logging',
        title: 'Quel Contrôle d\'Accès et Quelle Journalisation le Point de Terminaison Nécessite-t-il ?',
        content: [
          '**Un auditeur s\'attend à voir qui a appelé le modèle, avec quel identifiant, et quand — une exigence qu\'aucun des moteurs auto-hébergés courants ne satisfait sans passerelle en amont.** Ollama se lie par défaut à `127.0.0.1:11434` et n\'a pas de comptes utilisateurs ; vLLM et Hugging Face TGI exposent une API HTTP compatible OpenAI sans authentification intégrée.',
          'Utilisez une passerelle API (Kong, Envoy, ou la couche de gestion API d\'un fournisseur cloud) devant le moteur d\'inférence pour ajouter des clés API ou OAuth2 par appelant, puis journalisez chaque requête avec identité, horodatage, version du modèle et nombre de tokens vers un système ingérable par votre SIEM.',
        ],
        items: [
          '**Authentification** : clés API ou OAuth2 sur la passerelle, jamais un jeton partagé par tous les appelants',
          '**Autorisation** : accès basé sur les rôles — qui peut appeler quel modèle, qui voit les points de terminaison admin/métriques',
          '**Champs du journal d\'audit** : identité de l\'appelant, horodatage, modèle + version, point de terminaison appelé, statut de réponse',
          '**Accès admin** : MFA requis pour tout accès shell ou configuration à l\'hôte d\'inférence',
        ],
      },
