    seoTitle: 'SOC 2 e ISO 27001: LLMs autoalojados (2026)',
    intro: 'Preparar un despliegue de LLM autoalojado para una auditoría SOC 2 Type II o ISO 27001 significa demostrar los mismos controles que un auditor revisa en cualquier sistema de producción — control de acceso, cifrado, gestión de cambios, respuesta a incidentes — aplicados al endpoint de inferencia, los pesos del modelo y los registros de prompts. Esta guía mapea esos controles a las herramientas que realmente usan los equipos de TI: Ollama, vLLM, Hugging Face TGI y plataformas de inferencia empresariales.',
    metaDescription: 'Preparación SOC 2 Type II e ISO 27001 para stacks de LLM autoalojados: Trust Services Criteria, controles Annex A, registro de accesos, cifrado y riesgo de proveedor en modelos open-weight.',
