    snippetBlocks: [
      { type: 'one-sentence', content: 'La preparación SOC 2 e ISO 27001 para un LLM autoalojado requiere control de acceso y registro en el endpoint de inferencia, cifrado de pesos y registros, gestión de cambios, evaluación de riesgo de proveedor para modelos open-weight, un plan de respuesta a incidentes, una política de retención de registros y segmentación de red — nada de esto lo entrega por defecto ninguna herramienta de inferencia.' },
      { type: 'plain-terms', content: 'Un auditor no revisa si Ollama o vLLM está "certificado" — revisa si su organización puede demostrar quién accedió al modelo, qué cambió y cuándo, cómo se protegen los datos y qué ocurre ante un incidente. Esta guía no es asesoría legal ni de cumplimiento; confirme el alcance con su auditor.' },
    ],
