        note: 'Essas plataformas automatizam a coleta de evidências para o seu ambiente de controle mais amplo — elas não certificam sua infraestrutura de LLM auto-hospedada por si mesmas, e a PromptQuorum não tem atualmente relação de afiliação com nenhuma delas (apenas links de produto divulgados).',
