      commonMistakes: {
        id: 'common-mistakes',
        title: 'Quais São os Erros Mais Comuns na Preparação para Auditoria?',
        content: '**A maioria dos achados de auditoria em LLMs auto-hospedados vem de tratar o servidor de inferência como algo fora do ambiente normal de controle de TI.**',
        items: [
          '**Erro:** Assumir que uma ferramenta open source "auditável" (código visível) já foi auditada. **Correção:** documente sua própria avaliação de risco do publicador e do stack de serving.',
          '**Erro:** Deixar a API de inferência acessível sem gateway "porque é só interna". **Correção:** acessibilidade de rede não é o mesmo que controle de acesso — adicione autenticação mesmo assim.',
          '**Erro:** Registrar o texto completo do prompt no mesmo log de acesso usado para monitoramento de uptime. **Correção:** separe os dois repositórios.',
          '**Erro:** Tratar uma troca de versão de modelo como um deploy de rotina sem trilha de aprovação. **Correção:** aplique a mesma aprovação de gestão de mudanças usada para deployments de código.',
          '**Erro:** Não ter um plano de resposta a incidentes específico para os modos de falha do serving de modelo. **Correção:** adicione esses gatilhos ao seu plano de IR existente e teste-os pelo menos uma vez.',
        ],
      },
      checklist: {
        id: 'checklist',
        title: 'Qual É a Checklist de Preparação para Auditoria de um LLM Auto-Hospedado?',
        content: '**Percorra esta checklist antes de o trabalho de campo do seu auditor começar — cada item corresponde a uma categoria de controle abordada acima.**',
        numberedItems: [
          { title: 'Adicionar o sistema de LLM auto-hospedado à sua declaração de escopo ISMS/SOC 2', whyItMatters: 'Um sistema não documentado dentro do escopo é um achado mesmo que todo controle técnico esteja implementado.' },
          { title: 'Mapear os Trust Services Criteria ou controles Annex A relevantes ao seu stack real', whyItMatters: 'Auditores testam contra o mapeamento que você fornece.' },
          { title: 'Colocar um gateway autenticado na frente de cada endpoint de inferência', whyItMatters: 'Elimina o achado mais comum: uma API de modelo sem autenticação.' },
          { title: 'Ativar o log estruturado de requisições com identidade do chamador e timestamps', whyItMatters: 'É a evidência principal que um auditor solicita para o critério de segurança.' },
          { title: 'Criptografar o disco do host e o repositório de logs de prompts; exigir TLS no gateway', whyItMatters: 'Satisfaz o critério de confidencialidade e os controles criptográficos A.8.24.' },
          { title: 'Escrever e seguir um procedimento de gestão de mudanças para atualizações de modelo', whyItMatters: 'Prova integridade de processamento e dá um caminho de rollback documentado.' },
          { title: 'Documentar uma avaliação de risco de fornecedor para cada modelo open-weight em produção', whyItMatters: 'Fecha o controle mais comumente esquecido.' },
          { title: 'Publicar uma política de retenção e exclusão para logs de prompts/respostas', whyItMatters: 'Diretamente exigido para o critério de privacidade.' },
          { title: 'Segmentar o servidor de inferência em sua própria zona de rede', whyItMatters: 'Limita o raio de impacto e dá ao auditor um diagrama de rede claro.' },
          { title: 'Escrever um runbook de resposta a incidentes com gatilhos específicos do modelo e testá-lo uma vez', whyItMatters: 'Auditores verificam se o plano existe e foi exercitado.' },
        ],
      },
      faqSection: {
        id: 'faq',
        title: 'Perguntas Frequentes',
        faqs: [
          { q: 'Este artigo é aconselhamento jurídico ou de compliance?', a: 'Não. Este guia explica, em nível técnico, as categorias de controles que um auditor SOC 2 ou ISO 27001 costuma verificar. Ele não substitui um auditor qualificado ou sua área de compliance — consulte um antes de agendar uma auditoria ou fazer qualquer declaração de compliance.' },
          { q: 'Usar Ollama, vLLM ou Hugging Face TGI torna nossa infraestrutura de IA compatível com SOC 2?', a: 'Nenhuma ferramenta sozinha torna uma organização compliant. Compliance é um resultado de auditoria sobre o conjunto completo de controles da sua organização. Ollama, vLLM e TGI podem sustentar os requisitos técnicos (uma vez que você adicione autenticação, log e criptografia), mas nenhum é "compatível com SOC 2" ou "certificado ISO 27001" como produto de software.' },
          { q: 'Qual é a diferença entre SOC 2 Type I e Type II para infraestrutura de IA?', a: 'Type I avalia se os controles foram desenhados adequadamente em um determinado momento. Type II avalia se esses controles funcionaram efetivamente ao longo de um período de revisão, geralmente 6–12 meses. Para um endpoint de inferência, Type II significa que seus logs de acesso e evidências de gestão de mudanças precisam existir continuamente ao longo dessa janela inteira.' },
          { q: 'Modelos open-weight precisam de avaliação de risco de fornecedor mesmo sem um fornecedor de software?', a: 'Sim. O publicador do modelo (Meta, Mistral AI, Alibaba/Qwen ou outros) é uma parte da cadeia de suprimentos assim como um fornecedor SaaS. Uma avaliação documentada deve cobrir identidade do publicador, verificação de checksum dos pesos baixados, termos de licença e CVEs conhecidas no stack de serving que carrega o modelo.' },
          { q: 'Auto-hospedar um LLM reduz nosso escopo de auditoria em comparação com uma API de LLM em nuvem?', a: 'Isso muda o escopo em vez de simplesmente reduzi-lo. Auto-hospedagem elimina a relação de processador de dados terceirizado criada por uma API em nuvem, mas também significa que sua organização agora é dona de todo controle antes gerenciado pelo provedor de nuvem.' },
          { q: 'Que log um auditor espera ver no endpoint de inferência?', a: 'No mínimo: identidade do chamador (chave de API ou usuário autenticado), timestamp, modelo e versão chamados, endpoint e status da resposta, exportados para um repositório com acesso de escrita restrito. O conteúdo completo de prompts/respostas geralmente fica em um repositório separado e com controle de acesso mais rígido.' },
          { q: 'Por quanto tempo devemos reter logs de prompts como evidência de auditoria?', a: 'Não existe um número universal — depende da avaliação de risco da sua organização e das expectativas do seu auditor, equilibradas com os princípios de minimização de dados sob qualquer lei de privacidade aplicável. Defina uma janela de retenção específica por escrito, nunca "indefinidamente".' },
          { q: 'Plataformas como Vanta, Drata ou Secureframe conseguem monitorar um servidor de LLM auto-hospedado?', a: 'Elas automatizam bem a coleta de evidências para infraestrutura em nuvem, provedores de identidade e sistemas de tickets, mas um servidor de inferência auto-hospedado on-premise geralmente fica fora da lista de integrações padrão delas.' },
          { q: 'Qual é o achado de auditoria mais comum em infraestrutura de IA auto-hospedada?', a: 'Uma API de inferência acessível sem autenticação, justificada internamente como "só é acessível dentro da nossa rede". Acessibilidade de rede e controle de acesso são afirmações diferentes — um auditor espera autenticação no endpoint independentemente da posição na rede.' },
          { q: 'Devemos escolher vLLM/TGI ou uma plataforma de inferência corporativa para facilitar a preparação de auditoria?', a: 'vLLM e Hugging Face TGI dão controle total, mas exigem que você construa a camada de autenticação, log e criptografia. Plataformas corporativas costumam trazer RBAC e log de auditoria integrados, reduzindo o trabalho de instrumentação — mas de qualquer forma você precisa da documentação ISMS e da avaliação de risco de fornecedor ao redor.' },
        ],
      },
