    leadAnswerBlock: '**لا يوثّق SOC 2 ولا ISO 27001 أي برنامج بحد ذاته — بل يوثّقان ضوابط المؤسسة، وبنية LLM المستضافة ذاتيًا ليست سوى نظام واحد ضمن هذا النطاق.** يعني الاستعداد للتدقيق: التحكم بالوصول والتسجيل عند نقطة نهاية الاستدلال، تشفير أوزان النموذج وسجلات المحادثات أثناء التخزين والنقل، إدارة التغيير لتحديثات النموذج، تقييم موثّق لمخاطر الموردين حتى بالنسبة للنماذج مفتوحة الأوزان، خطة استجابة للحوادث لنظام تقديم النموذج، سياسة احتفاظ لسجلات المحادثات، وتجزئة الشبكة لخادم الاستدلال. هذا ليس استشارة قانونية أو امتثالية — استشر مدقق حساباتك قبل تحديد نطاق أي تدقيق.',
