    intro: '셀프호스팅 LLM 배포를 SOC 2 Type II 또는 ISO 27001 감사에 대비시킨다는 것은, 다른 모든 프로덕션 시스템에서 감사인이 확인하는 것과 동일한 통제 — 접근 제어, 암호화, 변경 관리, 사고 대응 — 을 추론 엔드포인트, 모델 가중치, 프롬프트 로그에 구체적으로 적용하는 것을 의미합니다. 본 가이드는 이러한 통제 항목을 실제로 사용하는 도구인 Ollama, vLLM, Hugging Face TGI, 그리고 엔터프라이즈 추론 플랫폼에 매핑합니다.',
