    leadAnswerBlock: '**SOC 2와 ISO 27001 모두 소프트웨어 자체를 인증하지 않습니다. 조직의 통제를 인증하며, 셀프호스팅 LLM 스택은 그 범위 내의 하나의 시스템일 뿐입니다.** 감사 준비란 추론 엔드포인트에 대한 접근 제어와 로깅, 모델 가중치와 프롬프트 로그의 저장 및 전송 시 암호화, 모델 업데이트에 대한 변경 관리, 오픈웨이트 모델이라도 문서화된 공급업체 위험 평가, 모델 서빙 시스템을 위한 사고 대응 계획, 프롬프트 로그 보존 정책, 추론 서버의 네트워크 분리를 의미합니다. 본 문서는 법률 또는 컴플라이언스 자문이 아닙니다. 감사 범위를 정하기 전 반드시 귀사의 감사인과 상담하십시오.',
